function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=t(message);$('toasts').append(el);setTimeout(()=>el.remove(),error?10000:5000);}
function run(fn){return async event=>{try{await fn(event);}catch(e){console.error(e.name,e.message);toast(e.message||'تعذّر تنفيذ العملية.',true);}};}
function bind(id,event,fn){$(id)?.addEventListener(event,run(fn));}
async function busy(button,fn){if(button?.disabled)return;const html=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner"></span> لحظة…';}try{return await fn();}finally{if(button){button.disabled=false;button.innerHTML=html;}}}
function objectURL(key,blob){if(state.urlMap.has(key))URL.revokeObjectURL(state.urlMap.get(key));const u=URL.createObjectURL(blob);state.urlMap.set(key,u);return u;}
function closeNav(){$('sidebar').classList.remove('open');$('nav-backdrop').hidden=true;$('nav-backdrop').classList.remove('visible');$('mobile-menu').setAttribute('aria-expanded','false');}
function route(){const page=location.hash.slice(1)||'clone';const valid=Object.hasOwn(pageNames,page)?page:'clone';document.body.dataset.activePage=valid;if(valid==='clone')void refreshCloneReferences();document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+valid));document.querySelectorAll('[data-page]').forEach(el=>{const active=el.dataset.page===valid;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});if(valid!=='youtube'){for(const id of ['reference-video','reference-audio'])$(id)?.pause();$('youtube-player')?.removeAttribute('src');if(youtubeCapture?.recorder?.state==='recording')youtubeCapture.recorder.stop();}else if(state.youtubeMeta&&!state.referenceFile&&!$('youtube-player').getAttribute('src')){$('youtube-player').src=embedURL(state.youtubeMeta.id,Number($('youtube-start').value),Number($('youtube-end').value));}$('page-crumb').textContent=pageNames[valid];document.title=t(pageNames[valid])+' — '+t('صوتك');closeNav();if(valid==='voices')renderVoices();if(valid==='history')renderHistory();if(valid==='models')renderModels();if(valid==='record')renderCaptures();if(valid==='stories')renderStory();window.scrollTo({top:0,behavior:'instant'});}
function connected(value,message=''){
 state.connected=value;syncEngineAvailability();const ready=value||state.mediaReady||state.deviceVoices.length>0;
 $('connection-badge').classList.toggle('connected',ready);
 $('connection-label').textContent=value?'محرك الاستنساخ متصل':state.mediaReady?'الأصوات الجاهزة متصلة':state.deviceVoices.length?'أصوات الجهاز متاحة':'الأصوات تحتاج اتصالًا';
 $('settings-connection-state').textContent=value?'متصل':'غير متصل';
 $('settings-connection-state').className='tag'+(value?' green':'');
 if(message){$('connection-diagnostics').textContent=message;$('connection-diagnostics').className='diagnostics '+(value?'success':'error');}
}
function requireEngine(){if(!state.connected){location.hash='settings';throw new Error('صل محرك الصوت أولًا من إعدادات الاتصال. التسجيل والتحرير متاحان في المتصفح.');}}
function engineAvailable(engine){
 return Boolean(engine) && (!engine.requiresRegistration ||
   (state.connected && state.models.some(model=>model.model_name===engine.model)));
}
function syncEngineAvailability(){
 const select=$('generation-engine');
 for(const option of select.options){
   option.disabled=!engineAvailable(engines.find(engine=>engine.id===option.value));
 }
 if(select.selectedOptions[0]?.disabled){
   select.value='edge';
   updateProfiles();
 }
}
function selectProfileForGeneration(profile){
 const engine=engines.find(entry=>entry.id===(profile.default_engine||profile.preset_engine||'chatterbox'));
 if(!engineAvailable(engine))throw new Error('المحرك المختار غير متاح على الخادم.');
 $('generation-engine').value=engine.id;
 $('generation-language').value=profile.language;
 updateProfiles();
 $('generation-profile').value=profile.id;
}
function currentEngine(){return engines.find(e=>e.id===$('generation-engine').value)||engines[0];}
function engineHint(){
 const e=currentEngine(),lang=$('generation-language').value;
 if(e.id==='edge')$('engine-hint').textContent=state.mediaReady?'أصوات جاهزة متصلة؛ يُرسل النص لخدمة Microsoft Edge للنطق. الحد 5000 حرف للمقطع.':'جارٍ الاتصال بخدمة الأصوات الجاهزة؛ يمكنك تجربة أصوات الجهاز أيضًا.';
 else if(e.id==='browser')$('engine-hint').textContent='قراءة مباشرة بأصوات المتصفح المتاحة على جهازك؛ لا ينتج عنها ملف للتنزيل.';
 else if(!engineAvailable(e))$('engine-hint').textContent='المحرك المختار غير متاح على الخادم.';
 else $('engine-hint').textContent=e.id==='chatterbox'?'استنساخ من عينة صوتية؛ يحتاج محرك استنساخ خاصًا متصلًا.':!e.languages.length?'تحقق من دعم اللغة على المحرك المثبت.':e.languages.includes(lang)?e.description:'اللغة المختارة غير مدعومة لهذا المحرك.';
 $('generation-instruct').disabled=e.requiresRegistration||['edge','browser','chatterbox','luxtts','chatterbox_turbo','kokoro'].includes(e.id);
 for(const id of ['generation-seed','personality-enabled','chunk-size','crossfade'])$(id).disabled=['edge','browser'].includes(e.id);
 $('model-size').disabled=e.requiresRegistration||['edge','browser'].includes(e.id);
}
function fillSelects(){for(const id of ['generation-language','profile-language'])$(id).innerHTML=Object.entries(languages).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('generation-engine').innerHTML=engines.map(e=>`<option value="${e.id}">${e.name}</option>`).join('');$('generation-language').value=getUILocale();$('generation-engine').value='edge';$('profile-language').value=getUILocale();profileTypeChanged();syncEngineAvailability();engineHint();}
function updateProfiles(){
 const selected=$('generation-profile').value,engine=$('generation-engine').value,lang=$('generation-language').value;
 let voices;
 if(engine==='edge')voices=state.readyVoices.filter(v=>v.Locale?.startsWith(lang+'-')).map(v=>({id:v.ShortName,name:readyVoiceName(v)}));
 else if(engine==='browser')voices=state.deviceVoices.filter(v=>v.lang.toLowerCase().startsWith(lang)).map(v=>({id:v.voiceURI,name:v.name+' — '+v.lang}));
 else if(currentEngine().requiresRegistration)voices=state.voices.filter(voice=>!voice.voice_type||voice.voice_type==='cloned');
 else voices=state.voices;
 $('generation-profile').innerHTML='<option value="">'+(voices.length?'اختر الصوت':'لا توجد أصوات متاحة لهذا الاختيار')+'</option>'+voices.map(v=>`<option value="${esc(v.id)}">${esc(v.name)}</option>`).join('');
 if(voices.some(v=>v.id===selected))$('generation-profile').value=selected;
 else if(voices.length)$('generation-profile').value=voices.find(v=>v.id==='ar-KW-FahedNeural')?.id||voices[0].id;
 $('voice-count').textContent=state.voices.length+state.readyVoices.length;
 renderVoices();engineHint();
}
async function refreshEngine(){
 requireEngine();
 const [profiles,history,models]=await Promise.allSettled([
   state.api.request('/profiles'),state.api.request('/history?limit=100'),state.api.request('/models/status')
 ]);
 if(models.status==='fulfilled'){
   state.models=models.value.models||[];
   syncEngineAvailability();
   renderModels();
 }
 if(profiles.status==='fulfilled')state.voices=profiles.value;
 updateProfiles();
 if(history.status==='fulfilled'){
   const data=history.value;
   state.history=data.items||data.history||data.generations||data;
   if(!Array.isArray(state.history))state.history=[];
   mergeLocalHistory();
   renderHistory();
 }
 const failed=[profiles,history,models].find(result=>result.status==='rejected');
 if(failed)toast(failed.reason.message,true);
}
async function connectEngine(){return await busy($('settings-form').querySelector('button[type=submit]'),async()=>{const base=validateBase($('api-url').value),token=$('api-token').value.trim();state.api=new VoiceboxAPI(base,token);state.models=[];storeWrite('voice-api-base',base);sessionWrite('voice-api-token',token);try{const health=await state.api.request('/health',{timeout:25000});if(!health||typeof health!=='object')throw new Error('رد الخدمة غير متوقع.');connected(true,'تم الوصول إلى محرك الصوت. تُقرأ الأصوات والنماذج من خادمك مباشرة.');await refreshEngine();toast('تم الاتصال بمحرك الصوت.');}catch(e){connected(false,e.message);renderModels();throw e;}finally{integrationSnippet();}});}
function integrationSnippet(){$('integration-snippet').textContent=`POST ${state.api.base||'https://your-server/api/voicebox'}/generate\nAuthorization: Bearer <SERVER_SIDE_KEY>\nContent-Type: application/json\n\n{\n  "profile_id": "YOUR_PROFILE_ID",\n  "text": "أهلًا وسهلًا",\n  "language": "ar",\n  "engine": "chatterbox",\n  "personality": false\n}`;}
function emptyState(iconName,title,copy,button=''){return `<div class="empty-state">${icon(iconName)}<h3>${esc(title)}</h3><p>${esc(copy)}</p>${button}</div>`;}
function renderVoices(){const query=$('voice-search').value.trim().toLowerCase(),type=$('voice-filter').value;const voices=state.voices.filter(p=>(!type||p.voice_type===type)&&(!query||p.name.toLowerCase().includes(query)));$('voices-grid').innerHTML=voices.length?voices.map((p,i)=>`<article class="voice-card"><div class="voice-card-top"><span class="voice-avatar">${esc(p.name.slice(0,1))}</span><div><h3>${esc(p.name)}</h3><span class="tag">${esc(typeLabel[p.voice_type]||'صوت')}</span></div></div><p translate="${p.description?'no':'yes'}">${esc(p.description||'ملف صوت قابل لإعادة الاستخدام.')}</p><div class="card-meta"><span>${esc(languages[p.language]||p.language)}</span><span>${Number(p.sample_count)||0} عينات</span><span>${Number(p.generation_count)||0} مقاطع</span></div><div class="button-group"><button class="button primary small" data-voice-action="use" data-id="${esc(p.id)}">استخدم الصوت</button><button class="icon-btn" data-voice-action="edit" data-id="${esc(p.id)}" aria-label="تعديل ${esc(p.name)}">${icon('sliders')}</button><button class="icon-btn" data-voice-action="samples" data-id="${esc(p.id)}" aria-label="عينات ${esc(p.name)}">${icon('folder')}</button><button class="icon-btn" data-voice-action="export" data-id="${esc(p.id)}" aria-label="تصدير ${esc(p.name)}">${icon('download')}</button><button class="icon-btn danger" data-voice-action="delete" data-id="${esc(p.id)}" aria-label="حذف ${esc(p.name)}">${icon('trash')}</button></div></article>`).join(''):emptyState('voices',state.connected?'أول صوت ينتظر منك البداية':'مكتبتك تبدأ بصوتك',state.connected?'أنشئ ملفًا من تسجيل واضح، أو اختر صوتًا جاهزًا من المحرك.':'صل خدمة الصوت لإدارة الملفات المستنسخة والجاهزة. تستطيع تسجيل العينة الآن.',`<button class="button primary" data-action="new-profile">${icon('plus')} أضف أول صوت</button>`);
 const ready=state.readyVoices.filter(v=>(!type||type==='preset')&&(!query||(readyVoiceName(v)+' '+v.ShortName).toLowerCase().includes(query)));
 const device=state.deviceVoices.filter(v=>v.lang?.toLowerCase().startsWith('ar')&&(!type||type==='preset')&&(!query||v.name.toLowerCase().includes(query)));
 if((ready.length||device.length)&&!voices.length)$('voices-grid').innerHTML='';
 const cards=ready.map(v=>`<article class="voice-card"><div class="voice-card-top"><span class="voice-avatar">${icon('wave')}</span><div><h3>${esc(readyVoiceName(v))}</h3><span class="tag green">جاهز — خدمة النطق</span></div></div><p>${esc(v.Locale)} · ${v.Gender==='Male'?'صوت رجالي':'صوت نسائي'}</p><p class="field-note">صوت جاهز من الخدمة، لا يستنسخ صوتك الشخصي.</p><button class="button primary small" data-ready-id="${esc(v.ShortName)}" data-ready-engine="edge">استخدم الصوت</button></article>`).join('');
 $('voices-grid').insertAdjacentHTML('afterbegin',cards+device.map(v=>`<article class="voice-card"><h3>${esc(v.name)}</h3><span class="tag">صوت الجهاز</span><p>${esc(v.lang)} · قراءة مباشرة دون ملف تنزيل.</p><button class="button secondary small" data-ready-id="${esc(v.voiceURI)}" data-ready-engine="browser">استمع بهذا الصوت</button></article>`).join(''));
}

async function profileTypeChanged(){const type=$('profile-type').value,old=$('profile-engine').value;const list=type==='preset'?engines.filter(e=>['kokoro','qwen_custom_voice'].includes(e.id)):type==='designed'?engines.filter(e=>e.id==='qwen_voice_design'):engines.filter(e=>!['edge','browser','kokoro','qwen_custom_voice','qwen_voice_design'].includes(e.id));$('profile-engine').innerHTML=list.map(e=>`<option value="${e.id}" ${engineAvailable(e)?'':'disabled'}>${e.name}</option>`).join('');if(list.some(e=>e.id===old&&engineAvailable(e)))$('profile-engine').value=old;$('clone-fields').hidden=type!=='cloned';$('preset-field').hidden=type!=='preset';$('design-field').hidden=type!=='designed';if(type==='preset')await loadPresets();}
async function loadPresets(){if(!state.connected){$('profile-preset').innerHTML='<option value="">صل المحرك لقراءة الأصوات الجاهزة</option>';return;}const data=await state.api.request('/profiles/presets/'+encodeURIComponent($('profile-engine').value));const voices=data.voices||data;$('profile-preset').innerHTML=Array.isArray(voices)?voices.map(p=>`<option value="${esc(p.id||p.voice_id||p.name)}">${esc(p.name||p.label||p.id)}</option>`).join(''):'';}
async function openProfile(id=''){const profile=state.voices.find(p=>p.id===id);$('profile-form').reset();$('edit-profile-id').value=id;$('profile-dialog-title').textContent=id?'تعديل الملف الصوتي':'أضف صوتًا جديدًا';$('profile-name').value=profile?.name||'';$('profile-description').value=profile?.description||'';$('profile-personality').value=profile?.personality||'';$('profile-language').value=profile?.language||getUILocale();$('profile-type').value=profile?.voice_type||'cloned';$('profile-form-error').textContent='';state.profileBlob=null;state.profileFilename='';$('profile-audio-label').textContent=id?'أضف عينة جديدة — اختياري':'ارفع عينة واضحة من 10–30 ثانية';await profileTypeChanged();if(profile){$('profile-engine').value=profile.default_engine||profile.preset_engine||'chatterbox';if(profile.voice_type==='preset'){await loadPresets();$('profile-preset').value=profile.preset_voice_id||'';}$('profile-design').value=profile.design_prompt||'';}$('profile-dialog').showModal();}
async function saveProfile(event){event.preventDefault();$('profile-form-error').textContent='';return await busy($('save-profile'),async()=>{try{requireEngine();const id=$('edit-profile-id').value,type=$('profile-type').value,engine=$('profile-engine').value,language=$('profile-language').value;const e=engines.find(e=>e.id===engine);if(!engineAvailable(e))throw new Error('المحرك المختار غير متاح على الخادم.');if(e.languages.length&&!e.languages.includes(language))throw new Error('المحرك المختار لا يدعم لغة النص.');if(type==='cloned'&&!id&&!state.profileBlob)throw new Error('ارفع تسجيلًا أو استخدم آخر تسجيل من الاستوديو.');if(state.profileBlob&&(!$('voice-permission').checked||!$('profile-reference').value.trim()))throw new Error('أكمل نص العينة وتأكيد صلاحية استخدام الصوت.');if(type==='preset'&&!$('profile-preset').value)throw new Error('اختر صوتًا جاهزًا متاحًا.');if(type==='designed'&&!$('profile-design').value.trim())throw new Error('أضف وصف الصوت المطلوب.');const data={name:$('profile-name').value.trim(),description:$('profile-description').value.trim()||null,language,voice_type:type,default_engine:engine,personality:$('profile-personality').value.trim()||null,preset_engine:type==='preset'?engine:null,preset_voice_id:type==='preset'?$('profile-preset').value:null,design_prompt:type==='designed'?$('profile-design').value.trim():null};if(!data.name)throw new Error('أدخل اسم الصوت.');const saved=await state.api.request('/profiles'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',data});$('edit-profile-id').value=saved.id;if(type==='cloned'&&state.profileBlob){const form=new FormData();form.append('file',state.profileBlob,state.profileFilename||'reference.webm');form.append('reference_text',$('profile-reference').value.trim());try{await state.api.request('/profiles/'+encodeURIComponent(saved.id)+'/samples',{method:'POST',data:form,timeout:300000});}catch(e){await refreshEngine();throw new Error('حُفظ الملف الصوتي، لكن رفع العينة لم يكتمل: '+e.message);}}$('profile-dialog').close();await refreshEngine();selectProfileForGeneration(saved);toast('تم حفظ الملف الصوتي.');}catch(e){$('profile-form-error').textContent=e.message;}});}
async function profileAction(event){const b=event.target.closest('[data-voice-action]');if(!b)return;requireEngine();const id=b.dataset.id,p=state.voices.find(p=>p.id===id);switch(b.dataset.voiceAction){case'use':selectProfileForGeneration(p);location.hash='generate';break;case'edit':await openProfile(id);break;case'export':download(await state.api.request('/profiles/'+encodeURIComponent(id)+'/export',{binary:true}),safeName(p.name)+'.zip');break;case'delete':if(confirmUI('حذف ملف «'+p.name+'»؟ قد يؤثر على العينات والأعمال المرتبطة به.')){await state.api.request('/profiles/'+encodeURIComponent(id),{method:'DELETE'});await refreshEngine();}break;case'samples':await showSamples(id);break;}}
async function showSamples(id){const samples=await state.api.request('/profiles/'+encodeURIComponent(id)+'/samples');$('samples-content').innerHTML=samples.length?samples.map(s=>`<div class="panel"><p>${esc(s.reference_text)}</p><audio controls data-sample="${esc(s.id)}"></audio><button class="button ghost small danger" data-delete-sample="${esc(s.id)}" data-profile="${esc(id)}">حذف العينة</button></div>`).join(''):'<p>لا توجد عينات لهذا الملف. أضف عينة من تعديل الملف الصوتي.</p>';$('samples-dialog').showModal();for(const audio of $('samples-content').querySelectorAll('audio')){const blob=await state.api.request('/samples/'+encodeURIComponent(audio.dataset.sample),{binary:true});audio.src=objectURL('sample-'+audio.dataset.sample,blob);}}
function scriptCount(){const text=$('generation-text').value;$('character-count').textContent=text.length.toLocaleString('en-US');storeWrite('voice-script',text);}
async function generate(event){event.preventDefault();if(['edge','browser'].includes($('generation-engine').value))return generateReady();requireEngine();if(state.job)throw new Error('توجد مهمة قيد التوليد. تابعها أو ألغها أولًا.');const text=$('generation-text').value.trim(),profile_id=$('generation-profile').value,e=currentEngine(),language=$('generation-language').value;if(!text)throw new Error('اكتب النص أولًا.');if(!engineAvailable(e))throw new Error('المحرك المختار غير متاح على الخادم.');if(!profile_id)throw new Error('أضف ملفًا صوتيًا أو اختر صوتًا جاهزًا.');if(e.languages.length&&!e.languages.includes(language))throw new Error('المحرك المختار لا يدعم لغة النص.');const profile=state.voices.find(p=>p.id===profile_id);if(profile?.voice_type==='preset'&&profile.preset_engine!==e.id)throw new Error('اختر المحرك المرتبط بالصوت الجاهز.');const data={text,profile_id,language,engine:e.id,model_size:$('model-size').value,personality:$('personality-enabled').checked,max_chunk_chars:Number($('chunk-size').value),crossfade_ms:Number($('crossfade').value)};const seed=$('generation-seed').value;if(seed!=='')data.seed=Number(seed);if(!$('generation-instruct').disabled&&$('generation-instruct').value.trim())data.instruct=$('generation-instruct').value.trim();$('generate-button').disabled=true;try{const job=await state.api.request('/generate',{method:'POST',data,timeout:60000});state.job=job.id;state.jobController=new AbortController();$('job-progress').hidden=false;$('output-empty').hidden=true;$('output-ready').hidden=true;$('output-state').textContent='قيد التوليد';const result=await state.api.pollGeneration(job.id,{signal:state.jobController.signal,onUpdate:item=>{$('job-message').textContent=item.status==='loading_model'?'جارٍ تحميل المحرك…':'جارٍ توليد الصوت…';}});const blob=await state.api.request('/audio/'+encodeURIComponent(result.id),{binary:true,timeout:120000});await setOutput(blob,result);toast('اكتمل المقطع. استمع إليه وراجع النطق.');}finally{state.job=null;state.jobController=null;$('generate-button').disabled=false;$('job-progress').hidden=true;if(!state.lastOutput){$('output-empty').hidden=false;$('output-state').textContent='بانتظار مقطع';}else{$('output-ready').hidden=false;$('output-state').textContent='آخر مقطع مكتمل';}await refreshEngine().catch(()=>{});}}
async function setOutput(blob,meta={}){$('browser-output').hidden=true;const buffer=await decodeAudio(blob);state.lastOutput={blob,buffer,meta};$('output-audio').src=objectURL('output',blob);$('output-empty').hidden=true;$('output-ready').hidden=false;$('output-state').textContent='مكتمل';$('output-state').className='tag green';$('output-duration').textContent=formatTime(buffer.duration)+' · '+(buffer.sampleRate/1000).toFixed(1)+' kHz';await drawWave(buffer,$('output-wave'));}
async function setRecording(blob,name='تسجيل جديد'){const buffer=await decodeAudio(blob);state.recordBlob=blob;state.recordName=name;state.recordBuffer=buffer;$('record-audio').src=objectURL('record',blob);$('record-preview').hidden=false;$('record-file-name').textContent=name+' · '+formatTime(buffer.duration);$('record-time').textContent=formatTime(buffer.duration);drawWave(buffer,$('record-wave'));}
async function toggleRecording(){if(!state.recording){try{await state.mic.start($('record-wave'));}catch(e){throw new Error(e.name==='NotAllowedError'?'اسمح للميكروفون من إعدادات المتصفح، أو ارفع تسجيلًا من جهازك.':e.message);}state.recording=true;$('record-toggle').classList.add('recording');$('record-toggle').innerHTML=icon('stop');$('record-toggle').setAttribute('aria-label','إيقاف التسجيل');$('recording-status').textContent='جارٍ التسجيل';$('record-instruction').textContent='اضغط للإيقاف وحفظ العينة';state.recordTimer=setInterval(()=>{const seconds=(Date.now()-state.mic.startedAt)/1000;$('record-time').textContent=formatTime(seconds);if(seconds>=300)toggleRecording().catch(e=>toast(e.message,true));},250);}else{state.recording=false;clearInterval(state.recordTimer);const blob=await state.mic.stop();$('record-toggle').classList.remove('recording');$('record-toggle').innerHTML=icon('mic');$('record-toggle').setAttribute('aria-label','ابدأ التسجيل');$('recording-status').textContent='اكتمل التسجيل';$('record-instruction').textContent='استمع إلى التسجيل قبل استخدامه';await setRecording(blob,'تسجيل '+new Date().toLocaleTimeString('ar-KW',{hour:'2-digit',minute:'2-digit'}));if(state.dictateTarget==='generator'){toast('اكتمل التسجيل؛ اضغط «فرّغ التسجيل» لإدخاله كنص.');}}}
function audioFilename(blob,prefix='recording'){const t=blob.type;return prefix+(t.includes('mp4')?'.m4a':t.includes('wav')?'.wav':t.includes('mpeg')?'.mp3':'.webm');}
async function saveRecording(){if(!state.recordBlob)throw new Error('سجّل أو ارفع مقطعًا أولًا.');const item={id:crypto.randomUUID(),name:state.recordName,createdAt:new Date().toISOString(),blob:state.recordBlob,transcript:$('transcript-text').value,duration:state.recordBuffer.duration};await localDB.put('captures',item);await renderCaptures();toast('حُفظ التسجيل على هذا الجهاز.');}
async function renderCaptures(){state.captures=await localDB.all('captures').catch(()=>[]);state.captures.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('captures-list').innerHTML=state.captures.length?state.captures.map(c=>`<div class="item-row"><span class="item-avatar">${icon('mic')}</span><div class="item-body"><span class="item-title">${esc(c.name)}</span><div class="item-meta"><span>${esc(new Date(c.createdAt).toLocaleDateString(getUILocale()))}</span><bdi class="mono">${formatTime(c.duration)}</bdi></div></div><div class="item-actions"><button class="icon-btn" data-capture-action="open" data-id="${esc(c.id)}" aria-label="فتح التسجيل">${icon('play')}</button><button class="icon-btn" data-capture-action="download" data-id="${esc(c.id)}" aria-label="تنزيل التسجيل">${icon('download')}</button><button class="icon-btn danger" data-capture-action="delete" data-id="${esc(c.id)}" aria-label="حذف التسجيل">${icon('trash')}</button></div></div>`).join(''):'<p class="empty-inline">التسجيلات التي تحفظها ستظهر هنا.</p>';$('storage-info').textContent=state.captures.length+' تسجيلات محفوظة في هذا المتصفح.';}
async function transcribe(blob){requireEngine();if(!blob)throw new Error('اختر تسجيلًا أو سجّل من الميكروفون أولًا.');const f=new FormData();f.append('file',blob,audioFilename(blob));const language=$('transcription-language').value;if(language)f.append('language',language);f.append('model',$('whisper-model').value);const result=await state.api.request('/transcribe',{method:'POST',data:f,timeout:600000});return result.text||'';}
async function addClip(blob,name='مقطع صوتي'){const buffer=await decodeAudio(blob);state.clips.push({id:crypto.randomUUID(),blob,name,duration:buffer.duration,start:0,trimStart:0,trimEnd:buffer.duration,volume:1,speed:1,track:0,muted:false});state.projectChanged=true;await persistProject();renderStory();toast('أُضيف المقطع إلى القصة.');}
async function persistProject(){await localDB.put('projects',{id:state.projectId,name:$('story-name').value,clips:state.clips,updatedAt:new Date().toISOString()});storeWrite('voice-project-id',state.projectId);}
function renderStory(){if(!state.clips.length){$('story-timeline').innerHTML='<div class="timeline-empty">'+icon('layers')+'<h3>مساحة لحكايتك القادمة</h3><p>أضف مقطعًا أو تسجيلًا، ثم حدّد مساره وتوقيته.</p></div>';return;}$('story-timeline').innerHTML=[...state.clips].sort((a,b)=>a.track-b.track||a.start-b.start).map(c=>`<article class="story-clip" data-clip="${esc(c.id)}"><div class="story-clip-head"><span class="item-avatar">${icon('wave')}</span><strong>${esc(c.name)}</strong><bdi class="mono subtle">${formatTime(c.duration)}</bdi><button class="icon-btn" data-clip-action="duplicate" data-id="${esc(c.id)}" aria-label="تكرار المقطع">${icon('copy')}</button><button class="icon-btn danger" data-clip-action="delete" data-id="${esc(c.id)}" aria-label="حذف المقطع">${icon('trash')}</button></div><div class="clip-strip" aria-hidden="true"></div><div class="clip-controls"><label>المسار<select data-clip-field="track">${[0,1,2,3].map(t=>`<option value="${t}" ${t===c.track?'selected':''}>${t+1}</option>`).join('')}</select></label><label>التوقيت (ث)<input type="number" data-clip-field="start" value="${c.start}" min="0" max="1800" step="0.1"></label><label>قص البداية<input type="number" data-clip-field="trimStart" value="${c.trimStart}" min="0" max="${c.duration}" step="0.1"></label><label>قص النهاية<input type="number" data-clip-field="trimEnd" value="${c.trimEnd}" min="0" max="${c.duration}" step="0.1"></label><label>مستوى الصوت<input type="number" data-clip-field="volume" value="${c.volume}" min="0" max="2" step="0.1"></label><label>السرعة<input type="number" data-clip-field="speed" value="${c.speed}" min="0.25" max="3" step="0.05"></label></div></article>`).join('');}
async function serializeProject(){return {format:'saad-voice-project',version:1,name:$('story-name').value,clips:await Promise.all(state.clips.map(async c=>{const {blob,...meta}=c;return {...meta,audio:await blobToDataURL(blob)};}))};}
async function importProject(data){if(data?.format!=='saad-voice-project'||data.version!==1||!Array.isArray(data.clips)||data.clips.length>60)throw new Error('ملف المشروع غير صالح أو يتجاوز 60 مقطعًا.');const clips=[];let bytes=0;for(const c of data.clips){const blob=await dataURLToBlob(c.audio);bytes+=blob.size;if(bytes>150*1024*1024)throw new Error('ملف المشروع كبير جدًا؛ الحد 150 ميجابايت.');const buffer=await decodeAudio(blob);for(const f of ['start','trimStart','trimEnd','volume','speed','track'])if(!Number.isFinite(c[f]))throw new Error('توقيتات المشروع غير صالحة.');if(c.start<0||c.trimStart<0||c.trimEnd<=c.trimStart||c.trimEnd>buffer.duration+.02||c.volume<0||c.volume>2||c.speed<.25||c.speed>3||c.track<0||c.track>3)throw new Error('إعدادات أحد مقاطع المشروع خارج الحدود المسموح بها.');clips.push({id:crypto.randomUUID(),name:String(c.name||'مقطع').slice(0,150),blob,duration:buffer.duration,start:c.start,trimStart:c.trimStart,trimEnd:c.trimEnd,volume:c.volume,speed:c.speed,track:c.track,muted:!!c.muted});}state.clips=clips;state.projectId=crypto.randomUUID();$('story-name').value=String(data.name||'قصة مستعادة').slice(0,100);await persistProject();renderStory();location.hash='stories';}
async function renderStoryAudio(downloadOnly=false){return await busy($(downloadOnly?'export-story':'play-story'),async()=>{const buffer=await mixStory(state.clips);const blob=encodeWav(buffer);if(downloadOnly){download(blob,safeName($('story-name').value)+'.wav');toast('تم دمج المقاطع وتصدير القصة.');}else{$('story-preview-audio').hidden=false;$('story-preview-audio').src=objectURL('story-preview',blob);await $('story-preview-audio').play();}});}
function createEffectSliders(){$('effects-sliders').innerHTML=effectDefinitions.map(e=>`<div class="effect-slider"><label for="fx-${e.id}"><span>${e.label}</span><output id="fx-out-${e.id}">${e.value}${e.unit}</output></label><input type="range" id="fx-${e.id}" min="${e.min}" max="${e.max}" step="${e.step}" value="${e.value}"></div>`).join('');for(const e of effectDefinitions)bind('fx-'+e.id,'input',()=>{$('fx-out-'+e.id).textContent=$('fx-'+e.id).value+e.unit;});}
function setEffects(values){for(const e of effectDefinitions){$('fx-'+e.id).value=values[e.id]??e.value;$('fx-out-'+e.id).textContent=$('fx-'+e.id).value+e.unit;}}
async function setEffectsSource(blob){state.effectsBlob=blob;state.effectsBuffer=await decodeAudio(blob);state.effectsResult=null;$('effects-original').hidden=false;$('effects-original').src=objectURL('effects-original',blob);$('effects-empty').hidden=true;$('effects-result').hidden=true;$('download-effects').disabled=true;$('fx-trim-start').value=0;$('fx-trim-end').value=state.effectsBuffer.duration.toFixed(3);drawWave(state.effectsBuffer,$('effects-wave'));}
async function processEffects(){if(!state.effectsBuffer)throw new Error('اختر ملفًا صوتيًا أولًا.');return await busy($('render-effects'),async()=>{const params=Object.fromEntries(effectDefinitions.map(e=>[e.id,Number($('fx-'+e.id).value)]));Object.assign(params,{trimStart:$('fx-trim-start').value,trimEnd:$('fx-trim-end').value,fadeIn:$('fx-fade-in').value,fadeOut:$('fx-fade-out').value});const buffer=await renderEffects(state.effectsBuffer,params);state.effectsResult=encodeWav(buffer);$('effects-result').src=objectURL('effects-result',state.effectsResult);$('effects-result').hidden=false;$('download-effects').disabled=false;toast('المعالجة جاهزة؛ استمع ثم نزّل النسخة.');});}
function statusTag(status){const names={completed:'مكتمل',generating:'قيد التوليد',loading_model:'تحميل المحرك',failed:'تعذّر التوليد',cancelled:'ملغى',canceled:'ملغى'};return `<span class="tag ${status==='completed'?'green':status==='failed'?'red':'amber'}">${names[status]||esc(status)}</span>`;}
function renderHistory(){const q=$('history-search').value.trim().toLowerCase(),filter=$('history-filter').value;const all=state.history.filter(h=>(!filter||(filter==='favorite'?h.is_favorited:h.status===filter))&&(!q||(h.text+' '+(h.profile_name||'')).toLowerCase().includes(q)));$('history-list').innerHTML=all.length?all.map(h=>`<article class="history-card"><div class="history-head"><div class="item-meta"><b>${esc(h.profile_name||state.voices.find(p=>p.id===h.profile_id)?.name||'ملف صوتي')}</b><span>${esc(new Date(h.created_at).toLocaleString(getUILocale()))}</span><bdi>${esc(h.engine||'')}</bdi></div>${statusTag(h.status)}</div><p class="history-text">${esc(h.text)}</p>${h.error?`<p class="field-note danger">${esc(h.error)}</p>`:''}<div class="item-actions"><button class="button secondary small" data-history-action="play" data-id="${esc(h.id)}" ${h.status!=='completed'?'disabled':''}>${icon('play')} استمع</button><button class="button ghost small" data-history-action="download" data-id="${esc(h.id)}" ${h.status!=='completed'?'disabled':''}>${icon('download')} WAV</button>${h.engine==='MOSS-TTS-Nano'&&h.id.startsWith('local-')?'':`<button class="button ghost small" data-history-action="mp3" data-id="${esc(h.id)}" ${h.status!=='completed'?'disabled':''}>MP3</button>`}<button class="icon-btn" data-history-action="favorite" data-id="${esc(h.id)}" aria-label="${h.is_favorited?'إزالة من المفضلة':'أضف إلى المفضلة'}">${icon('star')}</button><button class="icon-btn" data-history-action="reuse" data-id="${esc(h.id)}" aria-label="إعادة استخدام النص">${icon('copy')}</button>${h.status==='failed'?`<button class="button ghost small" data-history-action="retry" data-id="${esc(h.id)}">إعادة المحاولة</button>`:''}<button class="icon-btn danger" data-history-action="delete" data-id="${esc(h.id)}" aria-label="حذف العمل">${icon('trash')}</button></div><div id="history-player-${esc(h.id)}"></div></article>`).join(''):emptyState('clock','مساحة لكل أعمالك',state.connected?'ستظهر هنا المهام الجديدة فور إنشائها.':'صل محرك الصوت لقراءة سجل التوليد. تسجيلات هذا الجهاز في قسم التسجيل والتفريغ.');const recent=state.history.slice(0,3);$('recent-generations').innerHTML=recent.length?recent.map(h=>`<div class="item-row"><span class="item-avatar">${icon('wave')}</span><div class="item-body"><span class="item-title">${esc(h.text.slice(0,80))}</span><span class="item-meta">${esc(h.profile_name||'ملف صوتي')} · ${esc(h.engine||'')}</span></div>${statusTag(h.status)}<button class="icon-btn" data-history-action="output" data-id="${esc(h.id)}" ${h.status!=='completed'?'disabled':''} aria-label="تشغيل المقطع">${icon('play')}</button></div>`).join(''):'<p class="empty-inline">مساحة جاهزة لأول عمل بصوتك.</p>';}
async function historyAction(event){const b=event.target.closest('[data-history-action]');if(!b)return;if(state.localGenerations.some(h=>h.id===b.dataset.id))return localHistoryAction(b);requireEngine();const id=b.dataset.id,h=state.history.find(h=>h.id===id);return await busy(b,async()=>{switch(b.dataset.historyAction){case'play':{const blob=await state.api.request('/audio/'+encodeURIComponent(id),{binary:true});const target=$('history-player-'+id);const audio=document.createElement('audio');audio.controls=true;audio.src=objectURL('history-'+id,blob);target.replaceChildren(audio);await audio.play();break;}case'output':{await setOutput(await state.api.request('/audio/'+encodeURIComponent(id),{binary:true}),h);location.hash='generate';break;}case'download':download(await state.api.request('/audio/'+encodeURIComponent(id),{binary:true}),'voice-'+id.slice(0,8)+'.wav');break;case'mp3':download(await state.api.request('/history/'+encodeURIComponent(id)+'/export-audio?format=mp3',{binary:true,timeout:120000}),'voice-'+id.slice(0,8)+'.mp3');break;case'favorite':await state.api.request('/history/'+encodeURIComponent(id)+'/favorite',{method:'POST'});await refreshEngine();break;case'reuse':{const engine=engines.find(entry=>entry.id===(h.engine||'chatterbox'));if(!engineAvailable(engine))throw new Error('المحرك المختار غير متاح على الخادم.');$('generation-text').value=h.text;$('generation-language').value=h.language;$('generation-engine').value=engine.id;updateProfiles();$('generation-profile').value=h.profile_id;scriptCount();location.hash='generate';break;}case'retry':await state.api.request('/generate/'+encodeURIComponent(id)+'/retry',{method:'POST'});await refreshEngine();toast('أُعيدت المهمة إلى الطابور.');break;case'delete':if(confirmUI('حذف هذا العمل من الخادم؟')){await state.api.request('/history/'+encodeURIComponent(id),{method:'DELETE'});await refreshEngine();}break;}});}
function renderModels(){$('models-grid').innerHTML=engines.map(e=>`<article class="model-card"><div class="model-heading"><h3>${e.name}</h3>${icon('cpu')}</div><div class="tags"><span class="tag">${e.kind}</span>${e.languages.includes('ar')?'<span class="tag green">يدعم العربية</span>':''}${e.id==='omnivoice'?'<span class="tag amber">تجريبي</span>':''}${e.requiresRegistration?`<span class="tag ${engineAvailable(e)?'green':''}">${engineAvailable(e)?'متصل':'غير متصل'}</span>`:''}</div><p>${e.description}</p><div class="card-meta"><span>${e.languages.length?e.languages.length+' لغات':'حسب إصدار النموذج'}</span><bdi>${e.id}</bdi></div><button class="button secondary small" data-engine-use="${e.id}" ${engineAvailable(e)?'':'disabled'} style="margin-top:18px">اختيار المحرك</button></article>`).join('');$('runtime-model-count').textContent=state.connected?state.models.length+' نماذج':'غير متصل';$('runtime-model-list').innerHTML=state.models.length?state.models.map(m=>`<div class="item-row"><span class="item-avatar">${icon('cpu')}</span><div class="item-body"><bdi class="item-title">${esc(m.display_name||m.model_name)}</bdi><div class="item-meta"><bdi>${esc(m.model_name)}</bdi><span class="model-size">${m.size_mb?Math.round(m.size_mb)+' MB':''}</span></div></div><span class="tag ${m.loaded?'green':m.downloading?'amber':''}">${m.loaded?'في الذاكرة':m.downloading?'جارٍ التنزيل':m.downloaded?'مثبّت':'غير مثبّت'}</span><div class="item-actions">${m.downloading?`<button class="button ghost small" data-model-action="cancel" data-id="${esc(m.model_name)}">إلغاء</button>`:`<button class="button secondary small" data-model-action="${m.loaded?'unload':m.downloaded?'load':'download'}" data-id="${esc(m.model_name)}">${m.loaded?'تفريغ الذاكرة':m.downloaded?'تحميل':'تنزيل'}</button>`}</div></div>`).join(''):'<p class="empty-inline">صل المحرك لعرض النماذج المثبتة وحالتها الفعلية.</p>';}
async function modelAction(event){const b=event.target.closest('[data-model-action]');if(!b)return;requireEngine();return await busy(b,async()=>{const action=b.dataset.modelAction,id=b.dataset.id;const paths={download:'/models/download',load:'/models/load',unload:'/models/unload',cancel:'/models/download/cancel'};await state.api.request(paths[action],{method:'POST',data:{model_name:id},timeout:600000});toast(action==='download'?'بدأ تنزيل النموذج. حدّث الحالة لمتابعته.':'تم تنفيذ طلب النموذج.');await refreshEngine();});}
async function historyPicker() {requireEngine();const list=state.history.filter(h=>h.status==='completed');$('history-picker').innerHTML=list.length?list.map(h=>`<div class="item-row"><div class="item-body"><span class="item-title">${esc(h.text.slice(0,90))}</span><span class="item-meta">${esc(h.profile_name||'')}</span></div><button class="button secondary small" data-story-history="${esc(h.id)}">أضف</button></div>`).join(''):'<p>لا توجد مقاطع مكتملة في السجل بعد.</p>';$('select-history-dialog').showModal();}
async function openServerEffects(){requireEngine();if(!state.lastOutput?.meta.id)throw new Error('اختر مقطعًا مولّدًا من السجل أولًا.');const data=await state.api.request('/effects/available');state.effectOptions=data.effects||[];$('server-effect-controls').innerHTML=state.effectOptions.map((e,i)=>`<details class="advanced"><summary><label class="check-row"><input type="checkbox" id="server-fx-${i}">${esc(e.label||e.type)}</label></summary><p class="field-note">${esc(e.description)}</p><div class="form-grid">${Object.entries(e.params).map(([k,v])=>`<label>${esc(k)}<input type="number" id="server-fx-${i}-${esc(k)}" min="${v.min}" max="${v.max}" step="${v.step}" value="${v.default}"></label>`).join('')}</div></details>`).join('');$('server-effects-dialog').showModal();}
async function applyServerEffects(event){event.preventDefault();requireEngine();const effects_chain=state.effectOptions.map((e,i)=>({type:e.type,enabled:$('server-fx-'+i).checked,params:Object.fromEntries(Object.keys(e.params).map(k=>[k,Number($('server-fx-'+i+'-'+k).value)]))})).filter(e=>e.enabled);if(!effects_chain.length)throw new Error('اختر مؤثرًا واحدًا على الأقل.');const id=state.lastOutput.meta.id;await busy(event.submitter,async()=>{await state.api.request('/generations/'+encodeURIComponent(id)+'/versions/apply-effects',{method:'POST',data:{effects_chain,label:'معالجة الاستوديو',set_as_default:true},timeout:180000});const blob=await state.api.request('/audio/'+encodeURIComponent(id),{binary:true});await setOutput(blob,state.lastOutput.meta);$('server-effects-dialog').close();toast('حُفظ إصدار جديد بالمؤثرات.');});}
async function backup(){
 await busy($('backup-local'),async()=>{
  const captures=await localDB.all('captures');
  const projects=await localDB.all('projects');
  const assets=await localDB.all('assets');
  const serialClips=async clips=>await Promise.all(clips.map(async c=>{
   const {blob,...meta}=c;
   return {...meta,audio:await blobToDataURL(blob)};
  }));
  const data={
   format:'saad-voice-backup',version:1,
   assets:await Promise.all(assets.filter(a=>a.kind==='generation').map(async a=>{const {blob,...meta}=a;return {...meta,audio:await blobToDataURL(blob)};})),
   captures:await Promise.all(captures.map(async c=>{
    const {blob,...meta}=c;
    return {...meta,audio:await blobToDataURL(blob)};
   })),
   projects:await Promise.all(projects.map(async p=>({...p,clips:await serialClips(p.clips)})))
  };
  download(new Blob([JSON.stringify(data)],{type:'application/json'}),'voice-studio-backup.json');
 });
}
async function restoreBackup(file){if(file.size>200*1024*1024)throw new Error('النسخة أكبر من 200 ميجابايت.');const data=JSON.parse(await file.text());if(data.format!=='saad-voice-backup'||data.version!==1||!Array.isArray(data.captures)||!Array.isArray(data.projects)||data.captures.length>100||data.projects.length>30)throw new Error('صيغة النسخة الاحتياطية غير صالحة.');for(const c of data.captures){const blob=await dataURLToBlob(c.audio);const buffer=await decodeAudio(blob);await localDB.put('captures',{id:crypto.randomUUID(),name:String(c.name||'تسجيل مستعاد').slice(0,150),transcript:String(c.transcript||''),createdAt:new Date().toISOString(),duration:buffer.duration,blob});}for(const p of data.projects){await importProject({format:'saad-voice-project',version:1,name:p.name,clips:p.clips});}if(Array.isArray(data.assets)){for(const a of data.assets.slice(0,100)){const blob=await dataURLToBlob(a.audio);const buffer=await decodeAudio(blob);const {audio,...meta}=a;await localDB.put('assets',{...meta,id:'local-'+crypto.randomUUID(),kind:'generation',blob,duration:buffer.duration,status:'completed'});}await loadLocalGenerations();}await renderCaptures();toast('استُعيدت النسخة إلى هذا الجهاز.');}
