 bind('connection-badge','click',()=>location.hash='settings');bind('settings-form','submit',async e=>{e.preventDefault();await connectEngine();});bind('disconnect-engine','click',()=>{state.api.token='';sessionWrite('voice-api-token','');$('api-token').value='';state.voices=[];state.history=[];state.models=[];connected(false,'تم قطع الاتصال؛ الملفات المحلية متاحة.');updateProfiles();renderHistory();renderModels();});
