 bind('profile-form','submit',saveProfile);bind('profile-type','change',profileTypeChanged);bind('profile-engine','change',()=>{if($('profile-type').value==='preset')return loadPresets();});bind('profile-audio','change',async e=>{const f=e.target.files[0];if(!f)return;await decodeAudio(f);state.profileBlob=f;state.profileFilename=f.name;$('profile-audio-label').textContent=f.name;});bind('use-last-recording','click',()=>{if(!state.recordBlob)throw new Error('سجّل عينة في قسم التسجيل أولًا.');state.profileBlob=state.recordBlob;state.profileFilename=audioFilename(state.recordBlob);$('profile-audio-label').textContent='آخر تسجيل — '+formatTime(state.recordBuffer.duration);$('profile-reference').value=$('transcript-text').value;});bind('transcribe-reference','click',async()=>{await busy($('transcribe-reference'),async()=>{$('profile-reference').value=await transcribe(state.profileBlob);});});bind('voices-grid','click',profileAction);bind('voice-search','input',renderVoices);bind('voice-filter','change',renderVoices);bind('refresh-voices','click',async()=>{await loadReadyVoices();if(state.connected)await refreshEngine();});bind('import-profile','click',()=>{requireEngine();$('profile-import-file').click();});bind('profile-import-file','change',async e=>{const f=e.target.files[0];if(!f)return;const d=new FormData();d.append('file',f);await state.api.request('/profiles/import',{method:'POST',data:d,timeout:120000});await refreshEngine();e.target.value='';toast('تم استيراد الملف الصوتي.');});bind('samples-content','click',async e=>{const b=e.target.closest('[data-delete-sample]');if(b&&confirmUI('حذف هذه العينة؟')){await state.api.request('/profiles/samples/'+encodeURIComponent(b.dataset.deleteSample),{method:'DELETE'});await showSamples(b.dataset.profile);await refreshEngine();}});
