 bind('download-output','click',()=>{if(!state.lastOutput)throw new Error('لا يوجد مقطع مكتمل بعد.');download(encodeWav(state.lastOutput.buffer),'voice-output.wav');});bind('output-to-story','click',async()=>{if(!state.lastOutput)throw new Error('لا يوجد مقطع مكتمل بعد.');await addClip(state.lastOutput.blob,state.lastOutput.meta.text?.slice(0,50)||'مقطع مولّد');location.hash='stories';});bind('output-to-effects','click',async()=>{if(!state.lastOutput)throw new Error('لا يوجد مقطع مكتمل بعد.');location.hash='effects';await setEffectsSource(state.lastOutput.blob);});
