function readyVoiceName(v){const locales={'ar-KW':'الكويت','ar-SA':'السعودية','ar-AE':'الإمارات','ar-QA':'قطر','ar-BH':'البحرين','ar-OM':'عُمان','ar-EG':'مصر','ar-JO':'الأردن','ar-LB':'لبنان','ar-IQ':'العراق','ar-SY':'سوريا','ar-MA':'المغرب','ar-TN':'تونس','ar-DZ':'الجزائر'};const names={Fahed:'فهد',Noura:'نورة',Hamed:'حامد',Zariyah:'زارية',Hamdan:'حمدان',Fatima:'فاطمة',Salma:'سلمى',Shakir:'شاكر',Moaz:'معاذ',Amal:'أمل',Laila:'ليلى',Ali:'علي'};const short=(v.ShortName||'').split('-').slice(2).join('-').replace(/Neural$/,'');return t(names[short]||short)+' — '+t(locales[v.Locale]||v.Locale);}
