async function loadLocalGenerations(){state.localGenerations=(await localDB.all('assets').catch(()=>[])).filter(x=>x.kind==='generation');mergeLocalHistory();renderHistory();}
function mergeLocalHistory(){const remote=state.history.filter(h=>!h.id.startsWith('local-'));state.history=[...state.localGenerations,...remote].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));}
async function generateReady(){
 const text=$('generation-text').value.trim(),voice=$('generation-profile').value,engine=$('generation-engine').value;
 if(!text||!voice)throw new Error('اكتب النص واختر صوتًا متاحًا أولًا.');
 if(engine==='browser'){
  const speech=speakDevice(text,voice,$('generation-language').value);$('output-empty').hidden=true;$('output-ready').hidden=true;$('browser-output').hidden=false;$('output-state').textContent='قراءة من جهازك';
  speech.utterance.onerror=()=>toast('تعذّر تشغيل صوت الجهاز؛ جرّب صوتًا آخر أو خدمة الأصوات الجاهزة.',true);speech.start();return;
 }
 if(text.length>5000)throw new Error('قسّم النص إلى مقاطع لا تتجاوز 5000 حرف للأصوات الجاهزة.');
 await busy($('generate-button'),async()=>{
  $('browser-output').hidden=true;$('job-progress').hidden=false;$('cancel-job').hidden=true;$('job-message').textContent='جارٍ توليد المقطع بالصوت الجاهز…';
  try{
   const blob=await state.mediaApi.request('/speech',{method:'POST',data:{text,voice,rate:0,pitch:0},binary:true,timeout:115000});
   const buffer=await decodeAudio(blob);const v=state.readyVoices.find(v=>v.ShortName===voice);
   const meta={id:'local-'+crypto.randomUUID(),kind:'generation',blob,text,profile_id:voice,profile_name:v?readyVoiceName(v):voice,engine:'edge',language:$('generation-language').value,status:'completed',duration:buffer.duration,created_at:new Date().toISOString(),is_favorited:false};
   await localDB.put('assets',meta);await setOutput(blob,meta);await loadLocalGenerations();toast('المقطع جاهز للتشغيل والتنزيل.');
  }finally{$('job-progress').hidden=true;$('cancel-job').hidden=false;}
 });
}
async function localHistoryAction(button){
 const h=state.localGenerations.find(h=>h.id===button.dataset.id);if(!h)return;
 switch(button.dataset.historyAction){
  case'play':{const a=document.createElement('audio');a.controls=true;a.src=objectURL('local-'+h.id,h.blob);$('history-player-'+h.id).replaceChildren(a);await a.play();break;}
  case'output':await setOutput(h.blob,h);location.hash='generate';break;
  case'download':download(h.blob.type==='audio/wav'?h.blob:encodeWav(await decodeAudio(h.blob)),'voice-'+h.id.slice(-8)+'.wav');break;
  case'mp3':download(h.blob,'voice-'+h.id.slice(-8)+'.mp3');break;
  case'favorite':h.is_favorited=!h.is_favorited;await localDB.put('assets',h);await loadLocalGenerations();break;
  case'delete':if(confirmUI('حذف المقطع من هذا الجهاز؟')){await localDB.remove('assets',h.id);await loadLocalGenerations();}break;
  case'reuse':if(h.engine==='MOSS-TTS-Nano'){setCloneText(h.text);location.hash='clone';break;}$('generation-text').value=h.text;$('generation-engine').value='edge';$('generation-language').value=h.language;updateProfiles();$('generation-profile').value=h.profile_id;scriptCount();location.hash='generate';break;
 }
}
